def transform(n):
    """Applies the operation N -> k + 3d"""
    if n < 0:
        return -1 # Should not happen for positive integers
    if n == 0:
        # The problem context implies positive integers, but handling 0 defensively
        return 3 * 0 

    d = n % 10  # last digit
    k = n // 10 # remaining number
    return k + 3 * d

